    private static WeakReference<Bitmap> iconsSheet = new WeakReference<>(null);

    private String identifier;

    private int nameResId;

    private int legacy_id;

    private int iconX;

    private int iconY;

    private int color;
    private String iconPath;

    //@Nullable
    private WeakReference<Bitmap> icon;

//    ListingBlock(String identifier, int legacy_id, String name, int iconX, int iconY, int r, int g, int b,String iconPath) {
        ListingBlock(String identifier, int legacy_id, int nameResId, int iconX, int iconY, int r, int g, int b) {

        this.identifier = identifier;
        this.legacy_id = legacy_id;
        this.nameResId = nameResId;
        this.iconX = iconX;
        this.iconY = iconY;
//        this.iconPath = iconPath;
        if (r < 0)
            color = Color.TRANSPARENT;
        else
            color = Color.rgb(r, g, b);
        icon = new WeakReference<>(null);
    }

    public String getIdentifier() {
        return identifier;
    }
    public static ListingBlock getBlock(String identifier) {
        for (ListingBlock block : values()) {
            if (block.identifier.equals(identifier)) {
                return block;
            }
        }
        return null;
    }
    public int getNameResId() {
        return nameResId;
    }

    public int getColor() {
//        int color1 = color & 0xFFFFFF;
        return color;
    }

    public int getLegacy_id() {
        return legacy_id;
    }

    public String getName(Context context) {
        return context.getString(nameResId);
    }

    public Bitmap getIcon(AssetManager assMan) {
        Bitmap icon = this.icon.get();
        if (icon == null) {
            if (iconX >= 0) {
                Bitmap sheet = iconsSheet.get();
                try {
                    if (sheet == null) {
                        sheet = BitmapFactory.decodeStream(assMan.open("block_sprite_sheet.png"));
                        iconsSheet = new WeakReference<>(sheet);
                    }
                    icon = Bitmap.createBitmap(sheet, iconX, iconY, SIZE, SIZE);
                } catch (Exception e) {
                    e.printStackTrace();
                }
//            }else{
//                try {
//                    InputStream is = assMan.open(iconPath);
//                    Bitmap fullBmp = BitmapFactory.decodeStream(is);
//
//                    if (fullBmp != null) {
//                        int cropW = Math.min(fullBmp.getWidth(), tinyIconSizs);
//                        int cropH = Math.min(fullBmp.getHeight(), tinyIconSizs);
//
//                        icon = Bitmap.createBitmap(fullBmp, 0, 0, cropW, cropH);
//                    }
//                } catch (Exception e) {
//                    e.printStackTrace();
//                }
            }
            if (icon == null)
                icon = Bitmap.createBitmap(SIZE, SIZE, Bitmap.Config.ARGB_8888);
            this.icon = new WeakReference<>(icon);
        }
        return icon;
    }
